# command_name(lowercase) -> registry entry (first-match wins on rare
# collisions across plugins).
COMMAND_INDEX = {}
for _entry in COMMAND_REGISTRY:
    for _c in _entry["commands"]:
        COMMAND_INDEX.setdefault(_c, _entry)


def search_commands(query: str, limit: int = 10):
    """Very small keyword scorer over command names / module / function /
    description — good enough since command & module names in this codebase
    are already plain descriptive English words (terabox, ytdl, mediafire,
    broadcast, forward, rename, thumbnail, ...)."""
    q = (query or "").lower().strip()
    if not q:
        return []
    terms = [t for t in q.replace("/", " ").split() if t]
    scored = []
    for entry in COMMAND_REGISTRY:
        haystack = " ".join(entry["commands"] + [entry["module"], entry["function"], entry["description"]]).lower()
        score = 0
        for t in terms:
            if t in haystack:
                score += 2
            for c in entry["commands"]:
                if c.startswith(t) or t.startswith(c):
                    score += 3
        if score:
            scored.append((score, entry))
    scored.sort(key=lambda x: -x[0])
    out = []
    for _, entry in scored[:limit]:
        out.append({
            "command": entry["commands"][0],
            "aliases": entry["commands"][1:],
            "module": entry["module"],
            "admin_only": entry["admin_only"],
            "private_only": entry["private_only"],
            "group_only": entry["group_only"],
            "description": entry["description"],
        })
    return out
